<?php get_header();?><article class="article-single"><section class="page-hero shell"><span class="eyebrow"><?php echo esc_html(get_the_date('Y.m.d')); ?> · <?php echo esc_html(nexora_reading_time()); ?> <?php echo esc_html(nexora_t('min_read')); ?></span><h1><?php the_title(); ?></h1><p><?php echo esc_html(get_the_excerpt()); ?></p></section><?php if(has_post_thumbnail()):?><section class="article-feature shell-wide reveal"><?php the_post_thumbnail('full',['fetchpriority'=>'high','alt'=>nexora_image_alt('hero')]);?></section><?php endif;?><section class="article-body shell"><div class="prose"><?php the_content(); ?></div><?php nexora_share_links(); ?></section><section class="section shell"><div class="section-heading"><div><span class="eyebrow"><?php echo esc_html(nexora_t('related')); ?></span></div></div><div class="journal-grid"><?php $r=new WP_Query(['post_type'=>'post','posts_per_page'=>3,'post__not_in'=>[get_the_ID()],'suppress_filters'=>false]);while($r->have_posts()):$r->the_post();get_template_part('template-parts/journal-card');endwhile;wp_reset_postdata();?></div></section></article><?php get_footer(); ?>
